package com.example.workout.common.exception; import org.springframework.http.HttpStatus; public enum AppError { WORKOUT_NOT_FOUND(HttpStatus.NOT_FOUND,"WORKOUT_NOT_FOUND","Workout not found"), SHOE_NOT_FOUND(HttpStatus.NOT_FOUND,"SHOE_NOT_FOUND","Running shoe not found"), SHOE_IN_USE(HttpStatus.CONFLICT,"SHOE_IN_USE","Running shoe is referenced by workouts"), DUPLICATE_POSITION(HttpStatus.BAD_REQUEST,"DUPLICATE_POSITION","Positions must be unique within a workout"); private final HttpStatus status; private final String code; private final String message; AppError(HttpStatus s,String c,String m){status=s;code=c;message=m;} public HttpStatus status(){return status;} public String code(){return code;} public String message(){return message;} }
